const CACHE='horar-v1.2';const FILES=['./','./index.html','./style.css','./app.js','./engine.js','./reading.js','./journal.js','./places.js','./places-worker.js','./data/places-meta.json','./data/places-00.json.gz','./data/places-01.json.gz','./data/places-02.json.gz','./data/places-03.json.gz','./data/places-04.json.gz','./data/places-05.json.gz','./data/places-06.json.gz','./data/places-07.json.gz','./data/places-08.json.gz','./data/places-09.json.gz','./data/places-10.json.gz','./data/places-11.json.gz','./data/places-12.json.gz','./data/places-13.json.gz','./data/places-14.json.gz','./data/places-15.json.gz','./data/places-16.json.gz','./data/places-17.json.gz','./data/places-18.json.gz','./data/places-19.json.gz','./data/places-20.json.gz','./data/places-21.json.gz','./data/places-22.json.gz','./data/places-23.json.gz','./data/places-24.json.gz','./data/places-25.json.gz','./data/places-26.json.gz','./data/places-27.json.gz','./data/places-28.json.gz','./data/places-29.json.gz','./data/places-30.json.gz','./data/places-31.json.gz','./data/places-32.json.gz','./data/places-33.json.gz','./data/places-34.json.gz','./data/places-35.json.gz','./data/places-36.json.gz','./data/places-37.json.gz','./data/places-38.json.gz','./data/places-39.json.gz','./data/places-40.json.gz','./data/places-41.json.gz','./data/places-42.json.gz','./vendor/astronomy.js','./icon.svg','./manifest.webmanifest'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(e.request.method==='GET'&&new URL(e.request.url).origin===location.origin)e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));}return r;}).catch(()=>caches.match(e.request)));});
